from typing import Optional

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.tracer import tracer


class PreferencesMethods(BaseClient):
    """
    Методы группы 'Preferences' из https://im-docs.corp.mail.ru/
    """

    @tracer.start_as_current_span("preferences.wim_preference_getPermitDeny")
    def wim_preference_getPermitDeny(self) -> dict:
        """
        Метод для получения списка игнорируемых
        """
        return self.post("wim/preference/getPermitDeny", params={"aimsid": self.aimsid})

    @tracer.start_as_current_span("preferences.wim_preference_setPermitDeny")
    def wim_preference_setPermitDeny(
        self,
        pdIgnore: Optional[str] = None,
        pdIgnoreRemove: Optional[str] = None,
    ) -> dict:
        """
        Метод для удаления/добавления контактов/чатов в списки игнорируемых
        :param pdIgnore: sn для добавления
        :param pdIgnoreRemove: sn для удаления
        """
        data = {
            "aimsid": self.aimsid,
            "r": self.getReqId(),
            "pdIgnore": pdIgnore,
            "pdIgnoreRemove": pdIgnoreRemove,
        }

        for key, value in data.copy().items():
            if not value:
                data.pop(key)

        return self.post("wim/preference/setPermitDeny", params=data)
